insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_117'
from (values
('127.820.d.1.A',3,'A student looks up the Texas community college welding certificate path, the math classes it requires and the AWS certifications that follow. She is determining:','["academic knowledge and skills required for postsecondary education and careers", "only her snack order", "only a movie time", "only a game score"]'::jsonb,0,'Know requirements before choosing a path.','original'),
('127.820.d.1.A',4,'A student aiming for a welding inspector job should plan to study:','["only art history", "blueprint reading, math and welding codes", "only cooking", "only dance"]'::jsonb,1,'Inspection careers need these skills.','original'),
('127.820.d.1.B',3,'A fab shop supervisor tells new welders that customers expect clean welds, on-time delivery and polite answers to questions. These expectations help to:','["lose customers", "reduce sales", "foster positive customer satisfaction", "raise rework"]'::jsonb,2,'Meeting expectations satisfies customers.','original'),
('127.820.d.1.B',4,'A welder who notices a defect in a finished weld before shipping should:','["paint over it", "ignore it", "blame the next shift", "report and repair it before the customer receives it"]'::jsonb,3,'Quality starts with the welder.','original'),
('127.820.d.1.C',3,'A beginning welder wears his PPE, arrives on time and follows the shop''s procedures while treating coworkers politely. He is demonstrating:','["the professional standards required in the workplace", "casual habits", "careless habits", "random habits"]'::jsonb,0,'Professionalism includes respect and reliability.','original'),
('127.820.d.1.C',4,'Which habit best shows professionalism in a welding shop?','["ignoring the safety talk", "coming prepared and following procedures", "wearing flip-flops on the floor", "leaving scrap on the floor"]'::jsonb,1,'Preparation and procedure.','original'),
('127.820.d.1.D',3,'A student lists the AWS credentials she hopes to earn by graduation, then checks off the ones she already has each semester. She is evaluating:','["a dance", "a score", "progress toward personal career goals", "a menu"]'::jsonb,2,'Review progress against goals.','original'),
('127.820.d.1.D',4,'Checking progress toward a career goal each semester helps a student to:','["avoid the goal", "forget the plan", "skip every step", "adjust the plan and stay on track"]'::jsonb,3,'Progress checks guide corrections.','original'),
('127.820.d.1.E',3,'A welder asks the lead to restate the joint type, the filler metal and the inspection requirement before striking an arc on a new job. She is communicating to:','["clarify objectives and expectations in the workplace", "slow the team", "avoid work", "confuse the lead"]'::jsonb,0,'Clarify before starting.','original'),
('127.820.d.1.E',4,'If a welding procedure sheet is unclear, the welder should:','["use any rod", "ask the supervisor before welding", "guess", "skip the job"]'::jsonb,1,'Ask before welding.','original'),
('127.820.d.1.F',3,'A shop requires hearing protection near the grinders, a fire watch after hot work and a lockout/tagout before servicing equipment. These show knowledge and skills applied to:','["product advertising", "office decorating", "health and safety in the workplace as specified by OSHA", "shift bidding"]'::jsonb,2,'OSHA sets workplace safety.','original'),
('127.820.d.1.F',4,'A fire watch after welding is posted to:','["count the rods", "inspect the weld size", "check the time", "make sure no sparks or hot metal start a fire later"]'::jsonb,3,'Hot work can smolder.','original'),
('127.820.d.2.A',3,'Before striking an arc, a welder checks that the cables are not cracked, the ground clamp is secure and the work area is free of flammables. She is employing:','["welding equipment according to safety standards", "equipment carelessly", "equipment without checks", "equipment quickly"]'::jsonb,0,'Check equipment before use.','original'),
('127.820.d.2.A',4,'A frayed welding cable should be:','["taped and used", "replaced or repaired before use", "used outdoors only", "ignored"]'::jsonb,1,'Damaged cables are a shock and fire hazard.','original'),
('127.820.d.2.B',3,'A student puts used solvent rags and spent cleaning chemicals into labeled containers and sends them to a licensed hauler. She is identifying and properly disposing of:','["harmless water", "recyclable paper", "environmentally hazardous materials used with welding", "clean scrap"]'::jsonb,2,'Hazardous materials need proper disposal.','original'),
('127.820.d.2.B',4,'Used solvent from cleaning metal before welding should be:','["poured in a drain", "poured on the ground", "thrown in the trash", "collected for approved hazardous waste disposal"]'::jsonb,3,'Protect the environment.','original'),
('127.820.d.2.C',3,'A shop sorts steel, aluminum and copper scrap into separate bins that a recycler picks up each week. A student explains this to the class as part of:','["the importance of recycling materials used in welding", "hiding scrap", "burying scrap", "wasting materials"]'::jsonb,0,'Recycling conserves resources.','original'),
('127.820.d.2.C',4,'One benefit of recycling scrap metal from a welding shop is that it:','["costs more energy", "saves resources and energy compared to making new metal", "increases landfill", "wastes energy"]'::jsonb,1,'Recycling saves energy.','original'),
('127.820.d.2.D',3,'A student chooses a helmet with the correct shade lens, leather gloves, a flame-resistant jacket and safety glasses for a vertical weld. She is choosing:','["casual clothes", "fashion items", "appropriate personal protective equipment", "sports gear"]'::jsonb,2,'PPE protects from arc, heat and sparks.','original'),
('127.820.d.2.D',4,'A welding helmet lens is chosen mainly based on:','["its color alone", "the weld''s price", "the time of day", "the process and amperage being used"]'::jsonb,3,'Shade number matches the arc brightness.','original'),
('127.820.d.2.E',3,'After a mock inspection, a student rates her classmates'' shop practices on lockout, PPE, ventilation and fire safety and suggests fixes. She is evaluating:','["skills related to health and safety in the workplace as specified by OSHA", "only the music", "only the paint", "only the lighting"]'::jsonb,0,'Evaluate and improve safety.','original'),
('127.820.d.2.E',4,'A shop that has fumes collecting at the weld table should add:','["less lighting", "ventilation or fume extraction", "more cutting oil", "more noise"]'::jsonb,1,'Ventilation protects lungs.','original'),
('127.820.d.3.A',3,'A student studies a sketch that shows the plate sizes, the joint type and the weld symbols before cutting steel for a frame. She is demonstrating knowledge of:','["music sketches", "cooking sketches", "welding sketches", "landscape sketches"]'::jsonb,2,'Sketches guide fabrication.','original'),
('127.820.d.3.A',4,'A welding sketch is used to show:','["the price", "the weather", "the shop''s hours", "the sizes, joints and weld types needed"]'::jsonb,3,'It communicates the plan.','original'),
('127.820.d.3.B',3,'On a practice board, a student labels a triangular weld between two plates at a right angle, a weld in a beveled gap and a weld through a hole in one plate. She is identifying:','["types of welds such as fillet, groove, plug and spot", "types of knots", "types of sewing stitches", "types of paint strokes"]'::jsonb,0,'Weld types differ by joint.','original'),
('127.820.d.3.B',4,'A fillet weld joins two pieces that are:','["on top of each other only", "at an angle to each other, often 90 degrees", "in a straight line with a gap only", "not touching"]'::jsonb,1,'Fillets are triangular welds at corners and tees.','original'),
('127.820.d.4.A',3,'A welder calculates how many linear feet of weld a frame needs and how much wire that will use. She is demonstrating:','["only music skills", "only guessing", "mathematical skills related to welding", "only art skills"]'::jsonb,2,'Math estimates materials.','original'),
('127.820.d.4.A',4,'A frame needs 24 welds of 6 inches each. The total weld length is:','["120 inches", "30 inches", "72 inches", "144 inches"]'::jsonb,3,'24 × 6 = 144.','original'),
('127.820.d.4.B',3,'A student writes a one-page procedure with numbered steps that another welder can follow to set up the machine and weld a lap joint. She is demonstrating:','["technical writing skills related to welding", "poetry", "story writing", "journal writing"]'::jsonb,0,'Technical writing is clear and precise.','original'),
('127.820.d.4.B',4,'A good technical procedure for welding should be:','["unfinished", "clear, step by step and unambiguous", "vague", "humorous"]'::jsonb,1,'Procedures must be followed exactly.','original'),
('127.820.d.4.C',3,'A student reads a tape measure to the nearest sixteenth of an inch and confirms the same length with a steel rule before cutting plate. She is applying:','["careless guesses", "rounded numbers", "accurate readings of measuring devices", "random estimates"]'::jsonb,2,'Accurate reads prevent scrap.','original'),
('127.820.d.4.C',4,'Reading a tape measure to the nearest sixteenth means each mark is:','["1/8 inch apart only", "1/2 inch apart", "1 inch apart", "1/16 inch apart"]'::jsonb,3,'Smallest standard tape mark.','original'),
('127.820.d.4.D',3,'A welder picks a combination square to check a 90-degree corner, a tape for length and a fillet gauge to check weld size. She is accurately using:','["appropriate tools to make measurements", "the wrong tools", "no tools", "random tools"]'::jsonb,0,'Right tool, right measurement.','original'),
('127.820.d.4.D',4,'To measure the leg size of a fillet weld, a welder uses a:','["stopwatch", "fillet weld gauge", "thermometer", "protractor only"]'::jsonb,1,'Fillet gauges check leg size.','original'),
('127.820.d.4.E',3,'A welder cuts a 3 1/4-inch piece and a 2 5/8-inch piece from a bar and adds the lengths plus a 1/8-inch cut allowance to find the total stock needed. She is solving problems using:','["only words", "only whole numbers", "whole numbers, fractions, mixed numbers and decimals", "only guesses"]'::jsonb,2,'Shop math uses fractions and decimals.','original'),
('127.820.d.4.E',4,'What is 3 1/4 + 2 5/8 + 1/8?','["5 7/8", "6 1/4", "5 3/4", "6"]'::jsonb,3,'3.25 + 2.625 + 0.125 = 6.','original'),
('127.820.d.4.F',3,'A welder converts 5/8 inch to a decimal to enter it into a calculator and converts 0.375 inch back into a fraction to find a drill size. She is performing:','["conversions between fractions and decimals", "conversions of colors", "conversions of words", "conversions of music"]'::jsonb,0,'Fractions and decimals are interchangeable.','original'),
('127.820.d.4.F',4,'The decimal equivalent of 3/8 inch is:','["0.625", "0.375", "0.125", "0.250"]'::jsonb,1,'3 ÷ 8 = 0.375.','original'),
('127.820.d.4.G',3,'A welder converts a 2-inch plate thickness into millimeters to match a drawing made in a metric country. She is performing:','["conversions of time zones", "conversions of colors", "conversions between standard units and metric units", "conversions of music"]'::jsonb,2,'Standard to metric.','original'),
('127.820.d.4.G',4,'There are 25.4 millimeters in one inch, so a 1/4-inch plate is about:','["2.54 mm thick", "10 mm thick", "0.64 mm thick", "6.35 mm thick"]'::jsonb,3,'0.25 × 25.4 = 6.35.','original'),
('127.820.d.5.A',3,'A student interviews a pipe welder, a structural welder and a welding inspector to learn about their jobs and pay. She is:','["exploring careers in welding", "exploring recipes", "exploring dance", "exploring weather"]'::jsonb,0,'Career exploration informs choices.','original'),
('127.820.d.5.A',4,'A job-shadow day with a local welding shop helps a student by:','["replacing school", "showing real working conditions and requirements", "avoiding safety", "hiding the job"]'::jsonb,1,'Real-world exposure.','original'),
('127.820.d.5.B',3,'A class studies the AWS D1.1 structural code and the API 1104 pipeline standard to see how weld quality is judged. They are understanding:','["fashion codes", "cooking codes", "welding codes such as American Petroleum Institute standards", "game codes"]'::jsonb,2,'Codes define acceptable welds.','original'),
('127.820.d.5.B',4,'The American Petroleum Institute standard 1104 mainly covers welding of:','["furniture", "bicycles", "jewelry", "pipelines"]'::jsonb,3,'API 1104 is for pipelines.','original'),
('127.820.d.5.C',3,'Given a drawing and the materials, a student cuts, fits and welds a small steel cart with only a few questions to the instructor. She is working:','["independently to fabricate a variety of welded projects with minimal assistance", "only by copying", "only with help", "only by guessing"]'::jsonb,0,'Independent fabrication.','original'),
('127.820.d.5.C',4,'Before welding a project independently, the student should:','["weld without fitting", "read the drawing and check the fit-up", "skip the plan", "guess at the sizes"]'::jsonb,1,'Plan and fit first.','original'),
('127.820.d.5.D',3,'Two students share a welding booth, one holding the fit-up while the other tacks, then they switch and inspect each other''s welds. They are working:','["against each other", "alone only", "collaboratively with other students", "without talking"]'::jsonb,2,'Collaboration improves quality and safety.','original'),
('127.820.d.5.D',4,'When welding in pairs, the helper should always:','["leave the booth", "stand without gear", "watch the arc unprotected", "wear PPE and watch for hazards"]'::jsonb,3,'Safety applies to everyone nearby.','original'),
('127.820.d.6.A',3,'Before lighting a torch, a student checks for a clear area, secures the cylinders upright and has an extinguisher nearby. She is using:','["safe operating practices for oxy-fuel equipment", "careless practices", "rushed practices", "casual practices"]'::jsonb,0,'Oxy-fuel safety checks.','original'),
('127.820.d.6.A',4,'An oxy-fuel torch should never be lit with:','["a friction striker", "a match or lighter held near the tip", "a striker made for torches", "a spark lighter"]'::jsonb,1,'Use a striker, not a lighter.','original'),
('127.820.d.6.B',3,'A student chains the oxygen and acetylene cylinders upright to a cart, caps them when moving and cracks each valve slowly. She is performing:','["slow cleanup", "quick tidying", "safe handling of compressed gases", "hurried packing"]'::jsonb,2,'Compressed gas handling.','original'),
('127.820.d.6.B',4,'A compressed gas cylinder that is not in use should have:','["its valve open", "no support", "its cap off", "its valve closed and its cap on"]'::jsonb,3,'Prevents accidental release.','original'),
('127.820.d.6.C',3,'On a torch cart, a student points to the regulators, hoses, check valves, torch handle and cutting attachment and names each. She is identifying:','["components of oxy-fuel gas cutting", "parts of a bicycle", "parts of a piano", "parts of a camera"]'::jsonb,0,'Know the equipment.','original'),
('127.820.d.6.C',4,'The cutting attachment on an oxy-fuel torch adds a:','["water line", "separate oxygen lever for cutting", "gas hose for argon", "wire feeder"]'::jsonb,1,'The cutting oxygen lever delivers the cutting stream.','original'),
('127.820.d.6.D',3,'A student installs the correct tip, sets the working pressures, purges each line and lights the torch to a neutral flame. She is demonstrating:','["a tool change", "a shutdown", "proper set-up procedures for the oxy-fuel process", "a cleanup"]'::jsonb,2,'Set-up has an order.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Career Development' and d.language = 'en'
on conflict (fingerprint) do nothing;
insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_117'
from (values
('127.820.d.6.D',4,'Before lighting a torch, each gas line should be:','["filled with water", "left unpurged", "blocked", "purged briefly to clear air and mixed gas"]'::jsonb,3,'Purging avoids flashbacks.','original'),
('127.820.d.6.E',3,'A student finds that rusty plate, thick steel and a dull tip all change how well the torch cuts and writes down what to adjust. She is identifying:','["the factors affecting oxy-fuel cutting of base metals", "factors affecting cooking", "factors affecting weather", "factors affecting music"]'::jsonb,0,'Factors include thickness, tip size and speed.','original'),
('127.820.d.6.E',4,'Thicker steel generally requires an oxy-fuel cutting tip that is:','["no tip", "larger, with more heat and oxygen", "the same size", "smaller"]'::jsonb,1,'Thicker metal needs more heat.','original'),
('127.820.d.6.F',3,'A student pierces a hole through plate, cuts a straight line along a layout line and then cuts a bevel on an edge with the torch. She is demonstrating:','["only sanding", "only painting", "proper cutting techniques such as piercing, straight line and bevel cutting", "only measuring"]'::jsonb,2,'Cutting techniques differ.','original'),
('127.820.d.6.F',4,'To start a pierce on plate with an oxy-fuel torch, the operator should:','["use no preheat", "press the cutting lever first", "hold the tip very far away", "preheat the spot to a bright orange and then press the cutting lever"]'::jsonb,3,'Preheat before cutting oxygen.','original'),
('127.820.d.7.A',3,'Before starting a stick weld, the welder checks that the ground clamp is on clean metal, that she is standing on a dry surface and that her helmet is down. She is using:','["safe operating practices for shielded metal arc welding", "rushed practices", "casual practices", "careless practices"]'::jsonb,0,'Stick welding safety.','original'),
('127.820.d.7.A',4,'The electrode holder on a stick welder should never be placed:','["on a dry insulated stand", "on a damp or conductive surface while live", "in a rack", "on an insulated hook"]'::jsonb,1,'Live holders are hazardous.','original'),
('127.820.d.7.B',3,'A student sets up AC on one machine and DC electrode positive on another and learns how each affects arc stability and penetration. She is demonstrating knowledge of:','["music tempos", "cooking temperatures", "welding currents", "painting styles"]'::jsonb,2,'Current type affects the weld.','original'),
('127.820.d.7.B',4,'Direct current electrode positive (DCEP) generally provides:','["no arc", "shallower penetration only", "no penetration", "deeper penetration"]'::jsonb,3,'DCEP penetrates deeper.','original'),
('127.820.d.7.C',3,'A student explains that an arc between a coated electrode and the plate melts the base metal and the flux coating creates a shielding gas and slag. She is applying:','["shielded metal arc welding principles", "painting principles", "cooking principles", "gas welding principles"]'::jsonb,0,'Flux shields the weld.','original'),
('127.820.d.7.C',4,'The slag that forms on a stick weld is removed after welding with a:','["sponge", "chipping hammer and wire brush", "paper towel", "paint brush"]'::jsonb,1,'Chip and brush slag.','original'),
('127.820.d.7.D',3,'A student connects the ground, selects the amperage for a 1/8-inch electrode and checks the polarity before striking an arc. She is demonstrating:','["a shutdown", "a tool change", "proper set-up procedure for shielded metal arc welding", "a cleanup"]'::jsonb,2,'Set up before welding.','original'),
('127.820.d.7.D',4,'Amperage on a stick welder is set mainly according to:','["the shop''s name", "the time of day", "the helmet color", "the electrode diameter and type"]'::jsonb,3,'Match amperage to the electrode.','original'),
('127.820.d.7.E',3,'For a mild steel lap joint, a student picks an E6013 electrode; for a structural joint on thicker plate she picks an E7018. She is determining:','["appropriate electrodes for the base metal", "random electrodes", "cheap electrodes", "old electrodes"]'::jsonb,0,'Electrodes match the job.','original'),
('127.820.d.7.E',4,'An E7018 electrode should be stored:','["in a hot car", "in a dry, heated rod oven", "outdoors in rain", "in a wet bucket"]'::jsonb,1,'Low-hydrogen rods absorb moisture.','original'),
('127.820.d.7.F',3,'A student runs fillet welds on a T-joint in the flat, horizontal, vertical and overhead positions and then welds a beveled groove joint the same way. She is performing:','["only tack welds", "only flat welds", "fillet and groove welds in all positions", "only vertical welds"]'::jsonb,2,'All-position welding builds skill.','original'),
('127.820.d.7.F',4,'The four basic welding positions are flat, horizontal, vertical and:','["angled-only", "inverted-only", "underwater", "overhead"]'::jsonb,3,'1G/1F through 4G/4F.','original'),
('127.820.d.7.G',3,'A student grinds a 30-degree bevel on each plate, cleans the edges of rust and sets a root gap before welding. She is preparing:','["joints for welding", "the electrode for storage", "the weld for painting", "the shop for lunch"]'::jsonb,0,'Joint preparation affects quality.','original'),
('127.820.d.7.G',4,'Mill scale and rust are removed from the joint before welding because they can cause:','["a brighter weld", "porosity and weak welds", "better penetration", "a shorter arc"]'::jsonb,1,'Contamination weakens welds.','original'),
('127.820.d.8.A',3,'Before pulling the trigger on a wire welder, a student checks the gas flow, makes sure the spool is secure and keeps flammables away from the area. She is using:','["casual practices", "careless practices", "safe operating practices for gas metal arc welding", "rushed practices"]'::jsonb,2,'GMAW safety.','original'),
('127.820.d.8.A',4,'The shielding gas cylinder on a GMAW setup should be:','["kept near the arc", "laid flat", "left unsecured", "chained upright and capped when moved"]'::jsonb,3,'Cylinder safety.','original'),
('127.820.d.8.B',3,'A student explains that a wire electrode fed continuously through a gun carries current to the arc while a shielding gas protects the pool. She is applying:','["gas metal arc welding principles", "painting principles", "soldering principles", "stick welding principles"]'::jsonb,0,'GMAW uses wire and gas.','original'),
('127.820.d.8.B',4,'In gas metal arc welding, the wire is:','["added by hand each time", "fed automatically through the gun", "not used", "a stick"]'::jsonb,1,'Continuous wire feed.','original'),
('127.820.d.8.C',3,'A student threads the wire through the drive rolls, sets the tension, selects the gas flow rate and adjusts the voltage and wire speed. She is demonstrating:','["a tool change", "a cleanup", "proper set-up procedure for gas metal arc welding", "a shutdown"]'::jsonb,2,'Set up before welding.','original'),
('127.820.d.8.C',4,'If the wire speed is too high for the voltage on a GMAW machine, the arc will:','["burn the wire back instantly", "stop all spatter", "be too quiet", "stub into the plate and sound rough"]'::jsonb,3,'Wire speed and voltage must be balanced.','original'),
('127.820.d.8.D',3,'For thin sheet steel a student chooses a small wire diameter with a lower voltage, and for thicker plate she picks a larger wire and higher settings. She is using:','["appropriate equipment setup for the base metal in gas metal arc welding", "the same setup every time", "a random setup", "the cheapest setup"]'::jsonb,0,'Setup depends on the base metal.','original'),
('127.820.d.8.D',4,'Welding aluminum with GMAW typically calls for:','["no gas", "argon shielding gas and an aluminum wire", "a steel wire", "carbon dioxide only"]'::jsonb,1,'Aluminum needs argon and matching wire.','original'),
('127.820.d.8.E',3,'A student runs fillet and groove welds with short-circuit transfer on thin plate and spray transfer on thicker plate using the wire welder. She is performing:','["only sewing", "only gluing", "fillet and groove welds using gas metal arc welding with various metal transfer modes", "only tack welds"]'::jsonb,2,'Transfer modes vary with settings.','original'),
('127.820.d.8.E',4,'A metal transfer mode that works well on thin sheet metal is:','["none", "arc-off transfer", "spray transfer on very thin sheet", "short-circuit transfer"]'::jsonb,3,'Short circuit has lower heat input.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Career Development' and d.language = 'en'
on conflict (fingerprint) do nothing;
